def free_explicit_disclosure_repairs(raw, context, uid, statements):
    text = low(raw)
    whole = low(context)
    if 'confidential information' not in whole:
        return
    employee_clause = has_any(text, ['employees of the receiving party', 'employees of recipient', 'only to such employees of the receiving party', 'only to such employees of receiving party'])
    direct_permission = has_any(text, ['may disclose', 'may be disclosed'])
    inherited_permission = has_any(text, ['only to such employees', 'only to employees']) and has_any(whole, ['may disclose confidential information', 'may disclose the confidential information'])
    if employee_clause and (direct_permission or inherited_permission):
        conditions = []
        if has_any(text, ['strictly necessary', 'extent necessary', 'necessary for the permitted purpose']):
            conditions.append(['extent_necessary', raw])
        if has_any(text, ['confidentiality agreement', 'comply with this agreement', 'terms and conditions no less onerous']):
            conditions.append(['confidentiality_bound', raw])
        add_statement(statements, ['permission', ['receiving_party'], ['disclose', ['confidential_information'], ['employees_of', ['receiving_party']]], make_and(conditions)], [uid])
    anyone_prohibition = has_any(text, ['not to disclose it to anyone', 'not disclose it to anyone', 'not to disclose the confidential information to anyone'])
    if anyone_prohibition:
        exceptions = ['exception_set', ['cross_reference_exception', 'disclosure expressly permitted by this Agreement']]
        if has_any(text, ['prior written consent', 'prior written approval']):
            exceptions = ['add_exception', exceptions, ['authorization_exception', 'prior written consent of the other Party']]
        add_statement(statements, ['prohibition', ['receiving_party'], ['disclose', ['confidential_information'], ['third_parties']], ['no_condition'], exceptions], [uid])

def free_compose_acquired_policy(source_output, statements):
    actions = {}
    supports = {}
    links = []
    linked = set()
    for row in compose_rows(source_output):
        if not isinstance(row, dict):
            continue
        term = row.get('term')
        if not isinstance(term, list) or not term:
            continue
        if term[0] == 'acq_disposal_action_v3' and len(term) == 12:
            actions[term[2]] = term
            supports[term[2]] = list(row.get('support_ids', []))
        elif term[0] == 'acq_disposal_link_v3' and len(term) == 6:
            links.append([term, list(row.get('support_ids', []))])
        elif term[0] == 'acq_retention_v3' and len(term) == 7:
            actor = ['receiving_party']
            material = ['source_retention_material', term[6]]
            if term[2] == 'retention_permission':
                compose_add(statements, ['retention_permission', actor, material, ['after_disposal'], ['retention_condition', term[6]]], row.get('support_ids', []))
            elif term[2] == 'retention_prohibition':
                compose_add(statements, ['retention_prohibition', actor, material, ['after_disposal']], row.get('support_ids', []))
    for link, link_support in links:
        left_id = link[2]
        right_id = link[3]
        left = actions.get(left_id)
        right = actions.get(right_id)
        if left is None or right is None:
            continue
        left_action = free_policy_action(left)
        right_action = free_policy_action(right)
        left_trigger = free_policy_trigger(left[6], left[11])
        right_trigger = free_policy_trigger(right[6], right[11])
        if left_action is None or right_action is None or left_trigger is None or right_trigger is None:
            continue
        left_exception = free_policy_exception(left)
        right_exception = free_policy_exception(right)
        link_text = low(link[5])
        written_authorization = has_any(link_text, ['where expressly authorised in writing', 'where expressly authorized in writing'])
        authorized_pair = written_authorization and left_trigger == right_trigger and ((left[3] == 'return' and right[3] == 'destroy') or (left[3] == 'destroy' and right[3] == 'return'))
        if authorized_pair:
            if left[3] == 'return':
                returned = left_action
                destroyed = right_action
            else:
                returned = right_action
                destroyed = left_action
            action = ['authorized_action_alternative', returned, destroyed, link[5]]
            trigger = left_trigger
            exceptions = ['no_exceptions']
        elif link[4] == 'and' and left_trigger == right_trigger:
            action = ['action_conjunction', left_action, right_action]
            trigger = left_trigger
            exceptions = ['joint_branch_exception_scope_v4', left_exception, right_exception, link[5]]
        elif link[4] == 'or' and left_trigger == right_trigger:
            action = ['action_alternative', left_action, right_action]
            trigger = left_trigger
            exceptions = ['joint_branch_exception_scope_v4', left_exception, right_exception, link[5]]
        else:
            action = ['conditional_action_alternative_v4', left_action, left_trigger, left_exception, right_action, right_trigger, right_exception, link[5]]
            trigger = ['trigger_alternative', left_trigger, right_trigger]
            exceptions = ['joint_branch_exception_scope_v4', left_exception, right_exception, link[5]]
        support = compose_unique(supports.get(left_id, []) + supports.get(right_id, []) + link_support)
        compose_add(statements, ['disposal_obligation', ['receiving_party'], action, trigger, exceptions], support)
        linked.add(left_id)
        linked.add(right_id)
    for action_id, term in actions.items():
        if action_id in linked or not free_explicit_policy_atom(term):
            continue
        action = free_policy_action(term)
        trigger = free_policy_trigger(term[6], term[11])
        if action is not None and trigger is not None:
            compose_add(statements, ['disposal_obligation', ['receiving_party'], action, trigger, free_policy_exception(term)], supports.get(action_id, []))

