def sp_disclosure(spans,out,unresolved):
    i=0
    while i<len(spans):
        uid=spans[i].get('id')
        raw=spans[i].get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        text=sp_low(raw)
        context=sp_context(spans,i,2,1)
        ctext=sp_low(context)
        scope='unit:'+str(uid)
        permission=sp_any(ctext,['may disclose','may be disclosed','will disclose','restrict disclosure','restrict access','except in confidence','except its employees','except its employees,','only to disclose','disclosed only to','only to such employees','only to employees'])
        elliptical='obligations of the parties' in text and 'need to know' in text and not permission
        if elliptical:
            roles=[]
            if sp_any(text,['employee','staff','personnel']):
                roles.append('employee')
            if 'agent' in text:
                roles.append('agent')
            if 'representative' in text:
                roles.append('representative')
            for role in sp_unique(roles):
                sp_add(out,['acq_disclosure_v3',scope,'elliptical_recipient_permission_residual','receiving_party',role,'receiving_party','required','not_stated','required','source_stated_ellipsis',raw],[uid])
            if sp_any(text,['affiliate','any other individual','any other entity']):
                sp_add(out,['acq_disclosure_v3',scope,'elliptical_recipient_permission_residual','receiving_party','source_bounded_recipient','source_bounded','required','not_stated','required','source_stated_ellipsis',raw],[uid])
        need='required' if sp_any(ctext,['need to know','need-to-know','bona fide need']) else 'not_stated'
        extent='required' if sp_any(ctext,['extent necessary','extent absolutely necessary','strictly necessary','reasonably necessary','disclosure is necessary','involved in the performance']) else 'not_stated'
        confidentiality='written_required' if sp_any(ctext,['bound in writing','written agreement','written confidentiality agreement','mandatory non-disclosure agreement']) else 'required' if sp_any(ctext,['subject to the provisions','advise such employees','duty of confidentiality','bound by obligations','terms no less stringent','treat the confidential information']) else 'not_stated'
        effect='class_permission' if 'except' in ctext else 'operative_permission'
        actor='Auditor' if 'auditor shall' in text else 'Visitor' if 'visitor' in text else 'receiving_party'
        if permission:
            recipient_employee_coordination=sp_any(text,['employees or contractors of the recipient','employees and contractors of the recipient','employees and/or contractors of the recipient','employee or contractor of the recipient','contractors or employees of the recipient','contractors and employees of the recipient','contractors and/or employees of the recipient'])
            explicit_direct_employee=sp_any(text,["recipient’s employees","recipient's employees",'its employees','members of its staff','employees, officers','employees and/or consultants','except its employees','only to such employees of the receiving party','only to such employees of receiving party']) or recipient_employee_coordination
            controlled_employee=sp_any(text,['employees of companies directly or indirectly owned or controlled','employees, officials, representatives and agents of any legal entity that it controls','under common control'])
            employee_after_action=re.search(r'\b(?:disclos(?:e|ed)|access)\b[^.;:]{0,120}\bto\s+(?:those\s+|its\s+|the\s+)?employees\b',text,re.I) is not None
            direct_employee=explicit_direct_employee or (employee_after_action and not controlled_employee)
            if direct_employee:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'employee','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if controlled_employee:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'employee','controlled_entity',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'consultant' in text:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'consultant','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'contractor' in text:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'contractor','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'agent' in text:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'agent','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if sp_any(text,['professional adviser','professional advisor','advisors','advisers','legal advisor','legal adviser','financial advisor','financial adviser']):
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'professional_adviser','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'representatives' in text and not sp_any(text,['employees','consultants','contractors','agents','advisers','advisors']):
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'representative','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
        prohibited=sp_any(text,['shall not disclose','not disclose','not to disclose','will not without','not without']) and sp_any(text,['others','other person','other organization','third party','third parties','anyone'])
        if prohibited and not permission:
            exception='authorization' if sp_any(text,['consent','written approval','written authorization']) else 'source_stated_exception'
            sp_add(out,['acq_disclosure_v3',scope,'bounded_prohibition',actor,'source_outsiders','source_bounded','not_stated','not_stated','not_stated',exception,raw],[uid])
            if sp_any(text,['anyone','third party','third parties']):
                sp_add(out,['acq_disclosure_v3',scope,'bounded_prohibition',actor,'third_parties','source_bounded','not_stated','not_stated','not_stated',exception,raw],[uid])
        i+=1
